import { NextResponse } from "next/server";
import { db } from "../../../../src/prisma/db";

interface RouteContext {
  params: Promise<{
    id?: string;
    connectorId?: string;
  }>;
}

export async function PUT(
  request: Request,
  context: RouteContext
) {
  try {
    /*
     * Next.js dynamic route parameters are provided
     * as a Promise in the current App Router.
     */
    const params = await context.params;

    console.log("=================================");
    console.log("UPDATE CONNECTOR REQUEST");
    console.log("Params:", params);
    console.log("=================================");

    /*
     * Support either route naming:
     *
     * /api/connectors/[id]
     *
     * OR
     *
     * /api/connectors/[connectorId]
     */
    const idParam =
      params?.id ?? params?.connectorId;

    console.log("Connector ID parameter:", idParam);

    /*
     * Make sure we actually received an ID.
     */
    if (!idParam) {
      console.error(
        "Connector ID is missing.",
        params
      );

      return NextResponse.json(
        {
          error: "Connector ID is missing",
          params,
        },
        {
          status: 400,
        }
      );
    }

    /*
     * Convert the URL parameter to a number.
     */
    const id = Number(
      String(idParam).trim()
    );

    console.log("Parsed connector ID:", id);

    /*
     * Validate the ID.
     */
    if (!Number.isInteger(id) || id <= 0) {
      console.error(
        "Invalid connector ID:",
        idParam
      );

      return NextResponse.json(
        {
          error: "Invalid connector ID",
          receivedId: idParam,
        },
        {
          status: 400,
        }
      );
    }

    /*
     * Read the request body.
     */
    const body = await request.json();

    console.log("Update payload:", body);

    /*
     * Validate required fields.
     */
    if (
      !body.name ||
      !body.provider ||
      !body.model ||
      !body.prompt
    ) {
      return NextResponse.json(
        {
          error:
            "Name, provider, model, and prompt are required",
        },
        {
          status: 400,
        }
      );
    }

    /*
     * Get all connectors from the database.
     */
    const connectors =
      await db.orm.public.Connector.all();

    console.log(
      "Connectors in database:",
      connectors.map((connector) => ({
        id: connector.id,
        name: connector.name,
        provider: connector.provider,
        model: connector.model,
      }))
    );

    /*
     * Find the requested connector.
     */
    const existingConnector =
      connectors.find(
        (connector) =>
          connector.id === id
      );

    /*
     * Connector doesn't exist.
     */
    if (!existingConnector) {
      console.error(
        "Connector not found:",
        id
      );

      return NextResponse.json(
        {
          error: "Connector not found",
          connectorId: id,
        },
        {
          status: 404,
        }
      );
    }

    console.log(
      "Found connector:",
      existingConnector
    );

    /*
     * Update using Prisma ORM 8 syntax.
     */
    const updatedConnector =
      await db.orm.public.Connector
        .where({
          id,
        })
        .update({
          name: body.name,
          slug: body.slug,
          description: body.description,
          provider: body.provider,
          model: body.model,
          prompt: body.prompt,
          inputSchema: body.inputSchema,
          outputSchema: body.outputSchema,
          authType:
            body.authType ?? "api_key",
          isActive:
            body.isActive ?? true,
        });

    console.log(
      "Connector successfully updated:",
      updatedConnector
    );

    return NextResponse.json(
      updatedConnector
    );
  } catch (error) {
    console.error(
      "FAILED TO UPDATE CONNECTOR:",
      error
    );

    return NextResponse.json(
      {
        error:
          error instanceof Error
            ? error.message
            : "Failed to update connector",
      },
      {
        status: 500,
      }
    );
  }
}